"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Image from "next/image";
import { AnimatePresence, motion } from "framer-motion";
import { ArrowRight, Car, ChevronLeft, ChevronRight, Expand, Heart } from "lucide-react";
import { useTranslations } from "next-intl";
import { Link } from "@/i18n/navigation";
import { ImageLightbox } from "@/components/fleet/ImageLightbox";

const ease = [0.22, 1, 0.36, 1] as const;
const COUNT = 10;
const IDS = Array.from({ length: COUNT }, (_, i) => i + 1);
const SRC = IDS.map((id) => `/wed-${id}.webp`);

/**
 * Tiny inline previews (12px wide). They render instantly from the HTML, so a
 * photo fades in from its own colours instead of popping out of an empty box.
 */
const BLUR: Record<number, string> = {
  1: "data:image/jpeg;base64,",
  2: "data:image/jpeg;base64,",
  3: "data:image/jpeg;base64,",
  4: "data:image/jpeg;base64,",
  5: "data:image/jpeg;base64,",
  6: "data:image/jpeg;base64,",
  7: "data:image/jpeg;base64,",
  8: "data:image/jpeg;base64,",
  9: "data:image/jpeg;base64,",
  10: "data:image/jpeg;base64,",
};

function Placeholder() {
  return (
    <div className="flex h-full w-full items-center justify-center bg-surface-muted text-muted-foreground">
      <Car className="h-7 w-7" />
    </div>
  );
}

export function WeddingCarsSection() {
  const t = useTranslations("WeddingCars");
  const [active, setActive] = useState(0);
  const [broken, setBroken] = useState<Record<number, boolean>>({});
  const [lightbox, setLightbox] = useState<number | null>(null);
  const stripRef = useRef<HTMLDivElement | null>(null);

  const go = useCallback(
    (dir: 1 | -1) => setActive((i) => (i + dir + COUNT) % COUNT),
    [],
  );

  // Keep the filmstrip scrolled to whichever photo is showing.
  useEffect(() => {
    const strip = stripRef.current;
    const el = strip?.children[active] as HTMLElement | undefined;
    el?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
  }, [active]);

  return (
    <section className="border-y border-border bg-surface-muted/40">
      <div className="mx-auto grid w-full max-w-6xl grid-cols-1 items-center gap-12 px-4 py-16 sm:px-6 sm:py-24 lg:grid-cols-[minmax(0,5fr)_minmax(0,7fr)] lg:gap-16 lg:py-28">
        {/* ── Copy ── */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.55, ease }}
          className="flex flex-col"
        >
          <p className="mb-3 flex items-center gap-2.5 text-xs font-semibold uppercase tracking-[0.18em] text-brand-strong">
            <span className="h-px w-7 bg-brand" />
            {t("eyebrow")}
          </p>

          <h2 className="font-display text-[1.75rem] font-bold leading-[1.15] tracking-tight text-foreground sm:text-[2.5rem]">
            {t("heading")}
          </h2>

          <div className="mt-6 space-y-4 text-[15px] leading-relaxed text-muted-foreground sm:text-base">
            <p className="border-l-2 border-brand/40 pl-4 text-foreground">{t("p1")}</p>
            <p>{t("p2")}</p>
            <p>{t("p3")}</p>
          </div>

          <div className="mt-9">
            <Link
              href="/kontakt"
              className="group inline-flex w-full items-center justify-center gap-2 rounded-xl bg-brand px-6 py-3.5 text-sm font-semibold text-brand-foreground shadow-brand transition-colors hover:bg-brand-700 sm:w-auto"
            >
              <Heart className="h-4 w-4" />
              {t("cta")}
              <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-0.5" />
            </Link>
          </div>
        </motion.div>

        {/* ── Gallery ── */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.55, delay: 0.1, ease }}
          onKeyDown={(e) => {
            if (e.key === "ArrowRight") go(1);
            if (e.key === "ArrowLeft") go(-1);
          }}
        >
          <div className="group/gal relative aspect-[3/2] w-full overflow-hidden rounded-2xl border border-border bg-surface-muted shadow-card">
            <AnimatePresence mode="wait">
              <motion.div
                key={active}
                initial={{ opacity: 0, scale: 1.03 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.4, ease }}
                className="absolute inset-0"
              >
                {broken[active] ? (
                  <Placeholder />
                ) : (
                  <Image
                    src={SRC[active]}
                    alt={t("imageAlt", { n: active + 1 })}
                    fill
                    sizes="(max-width: 1023px) 100vw, 58vw"
                    placeholder="blur"
                    blurDataURL={BLUR[active + 1]}
                    className="object-cover"
                    onError={() => setBroken((b) => ({ ...b, [active]: true }))}
                  />
                )}
              </motion.div>
            </AnimatePresence>

            {/* Gradient only where the controls sit, so photos stay clean. */}
            <div
              aria-hidden
              className="pointer-events-none absolute inset-x-0 bottom-0 h-24 bg-gradient-to-t from-black/55 to-transparent"
            />

            <button
              type="button"
              onClick={() => setLightbox(active)}
              aria-label={t("imageAlt", { n: active + 1 })}
              className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-full bg-black/45 text-white opacity-0 outline-none backdrop-blur-sm transition-opacity duration-200 hover:bg-black/70 focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-white/70 group-hover/gal:opacity-100"
            >
              <Expand className="h-4 w-4" />
            </button>

            <div className="absolute bottom-3 left-4 font-display text-sm font-semibold tracking-wide text-white/95">
              {String(active + 1).padStart(2, "0")}
              <span className="text-white/55"> / {COUNT}</span>
            </div>

            <div className="absolute bottom-3 right-3 flex gap-2">
              {([-1, 1] as const).map((dir) => (
                <button
                  key={dir}
                  type="button"
                  onClick={() => go(dir)}
                  aria-label={dir === -1 ? "Prethodna" : "Sljedeća"}
                  className="flex h-9 w-9 items-center justify-center rounded-full bg-black/45 text-white outline-none backdrop-blur-sm transition-colors hover:bg-black/70 focus-visible:ring-2 focus-visible:ring-white/70"
                >
                  {dir === -1 ? (
                    <ChevronLeft className="h-4 w-4" />
                  ) : (
                    <ChevronRight className="h-4 w-4" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Filmstrip — scrolls instead of stacking into a second row. */}
          <div
            ref={stripRef}
            className="mt-3 flex snap-x snap-mandatory gap-2.5 overflow-x-auto pb-1 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          >
            {IDS.map((id, i) => {
              const on = i === active;
              return (
                <button
                  key={id}
                  type="button"
                  onClick={() => setActive(i)}
                  aria-label={t("imageAlt", { n: id })}
                  aria-pressed={on}
                  className={`relative h-16 w-24 shrink-0 snap-center overflow-hidden rounded-lg border outline-none sm:h-[4.5rem] sm:w-28 ${
                    on
                      ? "border-brand ring-2 ring-brand ring-offset-2 ring-offset-background"
                      : "border-border hover:border-brand/50"
                  } focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background`}
                >
                  {broken[i] ? (
                    <Placeholder />
                  ) : (
                    <Image
                      src={SRC[i]}
                      alt=""
                      aria-hidden
                      fill
                      sizes="112px"
                      placeholder="blur"
                      blurDataURL={BLUR[id]}
                      className="object-cover"
                      onError={() => setBroken((b) => ({ ...b, [i]: true }))}
                    />
                  )}
                  <motion.span
                    aria-hidden
                    className="absolute inset-0 bg-background"
                    initial={false}
                    animate={{ opacity: on ? 0 : 0.35 }}
                    transition={{ duration: 0.3, ease }}
                  />
                </button>
              );
            })}
          </div>
        </motion.div>
      </div>

      <ImageLightbox
        images={SRC}
        title={t("heading")}
        openIndex={lightbox}
        onClose={() => setLightbox(null)}
      />
    </section>
  );
}
